<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {CheckCheck,ChevronLeft,ChevronRight,Download,FileSpreadsheet,Info,Pencil,Plus,RefreshCw,School,Search,Trash2,UserRoundCheck} from 'lucide-vue-next'
import type {AccountDetail,AccountPage,AccountSummary,AdministrativeDivision,DownloadTicket,Gender,ImportIssue,ImportJob,JobAccepted,JobStatus,OrgUnit,Page,ProfileAddressInput,RoleCode,ShtongApi} from '@shtong/api-sdk'
import {errorMessage,importIssue,localTime,orgPath,roleCodes,saveBlob,zh} from '@shtong/web-shared'
import {useAction} from '../composables/useAction'
import ScopePicker from './ScopePicker.vue'
import ActionFeedback from './ActionFeedback.vue'
import AppDialog from './AppDialog.vue'

const props=defineProps<{api:ShtongApi;graduates?:boolean}>(),{busy,error,notice,run}=useAction()
const rows=ref<AccountSummary[]>([]),units=ref<OrgUnit[]>([]),selected=ref(new Set<string>()),reason=ref('账户维护')
const filters=reactive({q:'',lifecycleStatus:props.graduates?'GRADUATED':'ACTIVE',roleCode:'',orgUnitId:''})
type AccountFilters=typeof filters
const appliedFilters=ref<AccountFilters>({...filters}),pageSize=ref(20),selectingAll=ref(false),selectionProgress=ref(0)
// Frozen BulkAccountCommandRequest/SelectedAccounts limit; never truncate a selection.
const selectionLimit=5000
const querySnapshot=():AccountFilters=>({...filters,q:filters.q.trim()})
const filtersPending=computed(()=>JSON.stringify(querySnapshot())!==JSON.stringify(appliedFilters.value))
const hasFilters=computed(()=>Boolean(filters.q||filters.roleCode||filters.orgUnitId))
const showCreate=ref(false),showImport=ref(false),detail=ref<AccountDetail>(),showDetail=ref(false),showEdit=ref(false),showEnrollment=ref(false),importFile=ref<File>(),importJob=ref<ImportJob>(),importIssues=ref<ImportIssue[]>([]),temporary=ref('')
const importPicker=ref<HTMLInputElement>()
const create=reactive({loginName:'',displayName:'',personNo:'',gender:'' as Gender|'',classId:'',roleCode:'USER' as Exclude<RoleCode,'SYSTEM_ADMIN'>,scope:[] as string[]})
const blankAddress=():ProfileAddressInput=>({provinceCode:'',cityCode:'',districtCode:'',detail:''})
const edit=reactive({loginName:'',displayName:'',gender:'' as Gender|'',ethnicity:'',idCardNumber:'',mobileNumber:'',currentAddress:blankAddress(),householdAddress:blankAddress()}),enrollment=reactive({classId:''})
const editDivisions=reactive({provinces:[] as AdministrativeDivision[],currentCities:[] as AdministrativeDivision[],currentDistricts:[] as AdministrativeDivision[],householdCities:[] as AdministrativeDivision[],householdDistricts:[] as AdministrativeDivision[]})
const nextCursor=ref<string>(),cursor=ref<string>(),previous=ref<Array<string|undefined>>([]),pendingCommand=ref<'reset-password'|'delete'|'graduate'>(),credentialCommandId=ref(sessionStorage.getItem('shtong.pendingCredentialCommand')||'')
const selectedCount=computed(()=>selected.value.size),classes=computed(()=>units.value.filter(unit=>unit.type==='CLASS'&&unit.status==='ACTIVE'))
const commandNames={'reset-password':'重置密码',delete:'删除账户',graduate:'移入毕业生账户'}
function params(cursorValue?:string,query=appliedFilters.value,limit=pageSize.value){const p=new URLSearchParams({limit:String(limit)});Object.entries(query).forEach(([key,value])=>{if(value)p.set(key,value)});if(cursorValue)p.set('cursor',cursorValue);return p}
async function requestPage(cursorValue?:string,query=appliedFilters.value,limit=pageSize.value){return props.api.request<AccountPage>(`/system/accounts?${params(cursorValue,query,limit)}`)}
function showPage(data:AccountPage,cursorValue?:string){rows.value=data.items;cursor.value=cursorValue;nextCursor.value=data.hasMore?data.nextCursor||undefined:undefined}
async function load(){const data=await requestPage();showPage(data);previous.value=[]}
function resetQuery(){void run(async()=>{const query=querySnapshot(),data=await requestPage(undefined,query);appliedFilters.value=query;showPage(data);previous.value=[];selected.value=new Set()})}
function changePageSize(event:Event){const size=Number((event.target as HTMLSelectElement).value);void run(async()=>{try{const data=await requestPage(undefined,appliedFilters.value,size);pageSize.value=size;showPage(data);previous.value=[]}finally{(event.target as HTMLSelectElement).value=String(pageSize.value)}})}
function nextPage(){void run(async()=>{if(filtersPending.value||!nextCursor.value)return;const target=nextCursor.value,data=await requestPage(target);previous.value.push(cursor.value);showPage(data,target)})}
function previousPage(){void run(async()=>{if(filtersPending.value||!previous.value.length)return;const target=previous.value.at(-1),data=await requestPage(target);showPage(data,target);previous.value.pop()})}
function toggle(id:string){if(filtersPending.value)return;const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);if(next.size>selectionLimit){error.value=`一次最多选择 ${selectionLimit} 人，请缩小筛选范围`;return}selected.value=next}
function selectPage(){const next=new Set([...selected.value,...rows.value.map(row=>row.id)]);if(next.size>selectionLimit){error.value=`一次最多选择 ${selectionLimit} 人，请缩小筛选范围`;return}selected.value=next}
function selectAll(){void run(async()=>{
  selectingAll.value=true;selectionProgress.value=0
  try{
    const query=querySnapshot(),ids=new Set<string>(),seen=new Set<string>()
    let target:string|undefined,firstPage:AccountPage|undefined
    do{
      const data=await requestPage(target,query,target?200:pageSize.value)
      firstPage??=data
      data.items.forEach(row=>ids.add(row.id));selectionProgress.value=ids.size
      if(ids.size>selectionLimit){error.value=`结果超过 ${selectionLimit} 人，请缩小筛选范围后再全选；当前选择未改变`;return}
      if(!data.hasMore)break
      if(!data.nextCursor||seen.has(data.nextCursor)){error.value='分页数据异常，全选未完成，当前选择未改变，请重新查询';return}
      seen.add(data.nextCursor);target=data.nextCursor
    }while(target)
    if(firstPage){appliedFilters.value=query;showPage(firstPage);previous.value=[]}
    selected.value=ids
    notice.value=ids.size?`已全选${Object.values(query).some(Boolean)?'筛选结果':'全部账户'}，共 ${ids.size} 人`:'没有符合条件的账户'
  }finally{selectingAll.value=false}
})}
watch(filters,()=>{selected.value=new Set();notice.value='';error.value='';pendingCommand.value=undefined},{flush:'sync'})
function add(){void run(async()=>{if(create.roleCode!=='USER'&&!create.scope.length){error.value='请至少选择一个管理范围';return}const result=await props.api.request<{credential?:{temporaryPassword:string}}>('/system/accounts',{method:'POST',body:JSON.stringify({loginName:create.loginName,displayName:create.displayName,personNo:create.personNo,gender:create.roleCode==='USER'?(create.gender||null):null,classId:create.classId||null,roleAssignments:[{roleCode:create.roleCode,scopeCeilings:create.scope.map(orgUnitId=>({orgUnitId}))}],reason:reason.value})});temporary.value=result.credential?.temporaryPassword||'';notice.value='账户已创建';showCreate.value=false;Object.assign(create,{loginName:'',displayName:'',personNo:'',gender:'',classId:'',scope:[]});await load()})}
function openDetail(row:AccountSummary){void run(async()=>{detail.value=await props.api.request<AccountDetail>(`/system/accounts/${row.id}`);showDetail.value=true})}
function beginEdit(){if(!detail.value)return;Object.assign(edit,{loginName:detail.value.loginName,displayName:detail.value.displayName,gender:detail.value.gender||'',ethnicity:detail.value.ethnicity||'',idCardNumber:detail.value.idCardNumber||'',mobileNumber:detail.value.mobileNumber||'',currentAddress:detail.value.currentAddress?{provinceCode:detail.value.currentAddress.provinceCode,cityCode:detail.value.currentAddress.cityCode,districtCode:detail.value.currentAddress.districtCode,detail:detail.value.currentAddress.detail}:blankAddress(),householdAddress:detail.value.householdAddress?{provinceCode:detail.value.householdAddress.provinceCode,cityCode:detail.value.householdAddress.cityCode,districtCode:detail.value.householdAddress.districtCode,detail:detail.value.householdAddress.detail}:blankAddress()});showDetail.value=false;showEdit.value=true;if(detail.value.profileCompleted)void loadEditDivisions()}
async function loadEditDivisions(){try{editDivisions.provinces=await props.api.divisions('PROVINCE');await Promise.all([changeEditProvince('current',false),changeEditProvince('household',false)])}catch(caught){error.value=errorMessage(caught)}}
async function changeEditProvince(kind:'current'|'household',clear=true){const address=kind==='current'?edit.currentAddress:edit.householdAddress;if(clear){address.cityCode='';address.districtCode=''}try{const cities=address.provinceCode?await props.api.divisions('CITY',address.provinceCode):[];if(kind==='current')editDivisions.currentCities=cities;else editDivisions.householdCities=cities;await changeEditCity(kind,clear)}catch(caught){error.value=errorMessage(caught)}}
async function changeEditCity(kind:'current'|'household',clear=true){const address=kind==='current'?edit.currentAddress:edit.householdAddress;if(clear)address.districtCode='';try{const districts=address.cityCode?await props.api.divisions('DISTRICT',address.cityCode):[];if(kind==='current')editDivisions.currentDistricts=districts;else editDivisions.householdDistricts=districts}catch(caught){error.value=errorMessage(caught)}}
function saveEdit(){void run(async()=>{if(!detail.value)return;const sensitive=detail.value.profileCompleted?{idCardNumber:edit.idCardNumber,mobileNumber:edit.mobileNumber,currentAddress:edit.currentAddress,householdAddress:edit.householdAddress}:{};const updated=await props.api.request<AccountDetail>(`/system/accounts/${detail.value.id}`,{method:'PATCH',body:JSON.stringify({loginName:edit.loginName,displayName:edit.displayName,gender:detail.value.roleCodes.includes('USER')?(edit.gender||null):null,ethnicity:detail.value.roleCodes.includes('USER')?(edit.ethnicity||null):null,...sensitive,expectedVersion:detail.value.version,reason:reason.value})});detail.value=updated;rows.value=rows.value.map(row=>row.id===updated.id?updated:row);showEdit.value=false;showDetail.value=true;notice.value='账户资料已更正'})}
function beginEnrollment(){if(!detail.value)return;enrollment.classId=detail.value.classId||'';showDetail.value=false;showEnrollment.value=true}
function saveEnrollment(){void run(async()=>{if(!detail.value||!enrollment.classId)return;const updated=await props.api.request<AccountDetail>(`/system/accounts/${detail.value.id}/enrollment-change`,{method:'POST',body:JSON.stringify({classId:enrollment.classId,expectedVersion:detail.value.version,reason:reason.value})});detail.value=updated;rows.value=rows.value.map(row=>row.id===updated.id?updated:row);showEnrollment.value=false;showDetail.value=true;notice.value='学籍变动已完成，该学生需要重新登录'})}
function genderName(value?:Gender|null){return value==='MALE'?'男':value==='FEMALE'?'女':value==='OTHER'?'其他':'未填写'}
function runCommand(){void run(async()=>{if(!pendingCommand.value)return;const type=pendingCommand.value;const result=await props.api.request<JobAccepted>(`/system/accounts/commands/${type}`,{method:'POST',body:JSON.stringify({accountIds:[...selected.value],expectedCount:selectedCount.value,reason:reason.value})});pendingCommand.value=undefined;selected.value=new Set();if(type==='reset-password'){credentialCommandId.value=result.jobId;sessionStorage.setItem('shtong.pendingCredentialCommand',result.jobId)}notice.value=result.controlRequestId?'申请已提交，等待另一位管理员在“安全复核”中确认。':`${commandNames[type]}已完成`;await load()})}
async function saveTicket(ticket:DownloadTicket,name:string){saveBlob(await props.api.download(ticket),name)}
function downloadReset(){void run(async()=>{const id=credentialCommandId.value,status=await props.api.request<JobStatus>(`/system/account-commands/${id}`);if(status.state!=='COMPLETED'){notice.value=`重置密码：${zh(status.state)}`;return}const ticket=await props.api.request<DownloadTicket>(`/system/account-commands/${id}/credential-ticket`,{method:'POST'});await saveTicket(ticket,'重置后的初始密码.csv');credentialCommandId.value='';sessionStorage.removeItem('shtong.pendingCredentialCommand');notice.value='初始密码文件已下载，请妥善保管'})}
async function countFiltered(){let count=0,cursorValue:string|undefined;do{const data=await requestPage(cursorValue);count+=data.items.length;cursorValue=data.nextCursor||undefined}while(cursorValue);return count}
function exportAccounts(){void run(async()=>{if(filtersPending.value)return;if(reason.value.trim().length<2){error.value='请填写至少两个字的导出用途';return}const count=selectedCount.value||await countFiltered();if(!count){notice.value='没有可导出的账户';return}const query=appliedFilters.value,filter={...(query.q&&{q:query.q}),...(query.lifecycleStatus&&{lifecycleStatus:[query.lifecycleStatus]}),...(query.roleCode&&{roleCodes:[query.roleCode]}),...(query.orgUnitId&&{orgUnitIds:[query.orgUnitId]})};const selection=selectedCount.value?{mode:'SELECTED',accountIds:[...selected.value]}:{mode:'FILTERED_ALL',filter,expectedCount:count};const job=await props.api.request<JobAccepted>('/system/account-export/jobs',{method:'POST',body:JSON.stringify({selection,purpose:reason.value})});const status=await props.api.request<JobStatus>(`/system/account-export/jobs/${job.jobId}`);if(status.state!=='READY'){notice.value=`账户导出：${zh(status.state)}`;return}await saveTicket(await props.api.request<DownloadTicket>(`/system/account-export/jobs/${job.jobId}/download-ticket`,{method:'POST'}),'账户名单.csv');notice.value=`已导出 ${status.resultCount??count} 个账户`})}
function downloadTemplate(){void run(async()=>{saveBlob(await props.api.request<Blob>('/system/account-import/template'),'生化通账户导入模板.xlsx');notice.value='中文模板已下载'})}
function importAccounts(){void run(async()=>{if(!importFile.value)return;const data=new FormData();data.append('file',importFile.value);const accepted=await props.api.request<JobAccepted>('/system/account-import/jobs',{method:'POST',body:data});sessionStorage.setItem('shtong.pendingImport',accepted.jobId);await refreshImport(accepted.jobId);notice.value=`名单${zh(importJob.value?.state)}`})}
async function refreshImport(id:string){importJob.value=await props.api.request<ImportJob>(`/system/account-import/jobs/${id}`);importIssues.value=(await props.api.request<Page<ImportIssue>>(`/system/account-import/jobs/${id}/errors`)).items}
function commitImport(){void run(async()=>{if(!importJob.value)return;const job=importJob.value;await props.api.request<JobAccepted>(`/system/account-import/jobs/${job.id}/commit`,{method:'POST',body:JSON.stringify({validatedRevision:job.organizationRevision,expectedAccountCount:job.rowCount,reason:reason.value})});job.state='COMMITTED';notice.value=`已导入 ${job.rowCount} 个账户，请领取初始密码`;await load()})}
function downloadImport(){void run(async()=>{if(!importJob.value)return;await saveTicket(await props.api.request<DownloadTicket>(`/system/account-import/jobs/${importJob.value.id}/credential-ticket`,{method:'POST'}),'导入账户的初始密码.csv');sessionStorage.removeItem('shtong.pendingImport');importJob.value=undefined;importIssues.value=[];notice.value='初始密码文件已下载，请妥善保管'})}
function copyTemporaryPassword(){void run(async()=>{await navigator.clipboard.writeText(temporary.value);notice.value='初始密码已复制'})}
onMounted(()=>run(async()=>{await load();units.value=await props.api.request<OrgUnit[]>('/system/org-units');const id=sessionStorage.getItem('shtong.pendingImport');if(id&&!props.graduates){showImport.value=true;await refreshImport(id)}}))
</script>
<template><section class="view">
  <header class="page-header"><h1>{{graduates?'毕业生管理':'账户管理'}}</h1><div v-if="!graduates" class="row-actions"><button class="secondary" :disabled="busy" @click="showImport=!showImport"><FileSpreadsheet :size="18" aria-hidden="true"/>批量导入</button><button class="primary" :disabled="busy" @click="error='';showCreate=true"><Plus :size="18" aria-hidden="true"/>新增账户</button></div></header>
  <ActionFeedback :error="error" :notice="notice" :busy="busy"/>
  <form class="toolbar account-filters" @submit.prevent="resetQuery"><label class="search-field"><span class="sr-only">搜索账户</span><Search :size="18" aria-hidden="true"/><input v-model="filters.q" :disabled="busy" placeholder="姓名、登录账号或学工号"></label><select v-if="!graduates" v-model="filters.roleCode" :disabled="busy" aria-label="身份"><option value="">全部身份</option><option v-for="role in roleCodes" :key="role" :value="role">{{zh(role)}}</option></select><select v-model="filters.orgUnitId" :disabled="busy" aria-label="学院、年级或班级"><option value="">全部学院、年级和班级</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{orgPath(unit.id,units)}}</option></select><button class="secondary" :disabled="busy"><Search :size="18" aria-hidden="true"/>查询</button></form>
  <p v-if="filtersPending" class="notice" role="status">筛选条件已修改，尚未查询</p>
  <div class="selection-bar" :aria-busy="selectingAll"><strong>已选 {{selectedCount}} 人</strong><button :disabled="busy||filtersPending||!rows.length" @click="selectPage">选择本页</button><button :disabled="busy" @click="selectAll"><CheckCheck :size="18" aria-hidden="true"/><span>{{selectingAll?'正在全选':hasFilters?'全选筛选结果':'全部选择'}}</span></button><button v-if="selectedCount" :disabled="busy" @click="selected=new Set()">清空选择</button><template v-if="selectedCount&&!graduates"><button :disabled="busy" @click="error='';pendingCommand='reset-password'"><RefreshCw :size="18" aria-hidden="true"/><span>重置密码</span></button><button :disabled="busy" @click="error='';pendingCommand='graduate'"><UserRoundCheck :size="18" aria-hidden="true"/><span>移入毕业生</span></button><button class="danger-text" :disabled="busy" @click="error='';pendingCommand='delete'"><Trash2 :size="18" aria-hidden="true"/><span>删除</span></button></template><button :disabled="busy||filtersPending" @click="exportAccounts"><Download :size="18" aria-hidden="true"/><span>{{selectedCount?'导出已选':'导出当前查询的全部账户'}}</span></button><label class="reason-inline">操作原因或导出用途<input v-model="reason" minlength="2" maxlength="500"></label></div>
  <p v-if="selectingAll" role="status" aria-live="polite">正在读取全部结果，已读取 {{selectionProgress}} 人</p>
  <section v-if="showImport" class="import-section"><h2>批量导入账户</h2><div class="import-strip"><button class="secondary" :disabled="busy" @click="downloadTemplate"><Download :size="18" aria-hidden="true"/>下载中文模板</button><div class="file-picker"><label for="account-import-file">填写好的名单</label><input id="account-import-file" ref="importPicker" type="file" accept=".xlsx" hidden :disabled="busy" @change="importFile=($event.target as HTMLInputElement).files?.[0];importJob=undefined;importIssues=[]"><button class="secondary" :disabled="busy" @click="importPicker?.click()"><FileSpreadsheet :size="18" aria-hidden="true"/>选择名单文件</button><span aria-live="polite">{{importFile?.name||'尚未选择文件'}}</span></div><button class="primary" :disabled="busy||!importFile" @click="importAccounts">检查名单</button></div><div v-if="importJob" class="import-review"><strong>{{zh(importJob.state)}}：{{importJob.rowCount}} 人，{{importJob.errorCount}} 个问题</strong><ul v-if="importIssues.length" class="issue-list"><li v-for="(issue,index) in importIssues" :key="index">{{zh(issue.sheet)}} 第 {{issue.row}} 行 · {{zh(issue.field)}}：{{importIssue(issue.code)}}</li></ul><div class="form-actions"><button v-if="importJob.state==='VALID'" class="primary" :disabled="busy" @click="commitImport">确认导入 {{importJob.rowCount}} 人</button><button v-if="importJob.state==='COMMITTED'" class="primary" :disabled="busy" @click="downloadImport"><Download :size="18" aria-hidden="true"/>领取初始密码（仅一次）</button></div></div></section>
  <div v-if="credentialCommandId" class="import-review"><strong>重置密码申请已提交</strong><button class="secondary" :disabled="busy" @click="downloadReset"><Download :size="18" aria-hidden="true"/>查看结果并领取初始密码</button></div>
  <div class="table-wrap"><table><thead><tr><th>选择</th><th>账户</th><th>学工号</th><th>{{graduates?'毕业原因':'身份'}}</th><th>账户状态</th><th>{{graduates?'毕业时间':'密码'}}</th><th>详情</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="7" class="empty">{{busy?'正在加载':'没有匹配账户'}}</td></tr><tr v-for="row in rows" :key="row.id"><td><input type="checkbox" :checked="selected.has(row.id)" :aria-label="`选择 ${row.displayName}`" :disabled="busy||filtersPending" @change="toggle(row.id)"></td><td><strong>{{row.displayName}}</strong><small>{{row.loginName}}</small></td><td>{{row.personNo}}</td><td><span v-if="graduates">{{row.graduatedReason||'历史毕业档案'}}</span><span v-for="role in row.roleCodes" :key="role" class="tag">{{zh(role)}}</span></td><td><span class="status" :class="row.lifecycleStatus.toLowerCase()">{{zh(row.lifecycleStatus)}}</span><small v-if="row.securityStatus!=='NORMAL'">{{zh(row.securityStatus)}}</small></td><td>{{graduates?localTime(row.graduatedAt):row.passwordChangeRequired?'首次登录需改密':'正常'}}</td><td><button class="icon-button" :disabled="busy" :title="`查看${row.displayName}详情`" :aria-label="`查看 ${row.displayName} 详情`" @click="openDetail(row)"><Info :size="19" aria-hidden="true"/></button></td></tr></tbody></table></div>
  <nav class="pagination account-pagination" aria-label="账户列表分页"><label>每页条数<select :value="pageSize" :disabled="busy||filtersPending" @change="changePageSize"><option v-for="size in [10,20,50,100]" :key="size" :value="size">{{size}} 条</option></select></label><span aria-live="polite">第 {{previous.length+1}} 页 · 本页 {{rows.length}} 人{{nextCursor?'':' · 已到末页'}}</span><div class="pagination-buttons"><button class="secondary" :disabled="busy||filtersPending||!previous.length" @click="previousPage"><ChevronLeft :size="18" aria-hidden="true"/>上一页</button><button class="secondary" :disabled="busy||filtersPending||!nextCursor" @click="nextPage">下一页<ChevronRight :size="18" aria-hidden="true"/></button></div></nav>
  <AppDialog v-if="showCreate" title="新增账户" :busy="busy" @close="showCreate=false"><form @submit.prevent="add"><label>姓名<input v-model="create.displayName" required maxlength="100"></label><label>学工号<input v-model="create.personNo" required maxlength="100"></label><label>登录账号<input v-model="create.loginName" required maxlength="100" autocomplete="off"></label><label>身份<select v-model="create.roleCode"><option v-for="code in roleCodes.filter(code=>code!=='SYSTEM_ADMIN')" :key="code" :value="code">{{zh(code)}}</option></select></label><label v-if="create.roleCode==='USER'">性别（选填）<select v-model="create.gender"><option value="">未填写</option><option value="MALE">男</option><option value="FEMALE">女</option><option value="OTHER">其他</option></select></label><label>所属班级{{create.roleCode==='USER'?'（必选）':'（可选）'}}<select v-model="create.classId" :required="create.roleCode==='USER'"><option value="">请选择班级</option><option v-for="unit in classes" :key="unit.id" :value="unit.id">{{orgPath(unit.id,units)}}</option></select></label><ScopePicker v-model="create.scope" :units="units" :role="create.roleCode"/><label>操作原因<input v-model="reason" required minlength="2" maxlength="500"></label><ActionFeedback :error="error"/><button class="primary" :disabled="busy">{{busy?'正在创建':'创建账户'}}</button></form></AppDialog>
  <AppDialog v-if="temporary" title="账户已创建" @close="temporary=''"><p>初始密码仅显示一次，请妥善交给本人。</p><label>初始密码<input :value="temporary" readonly></label><button class="secondary" @click="copyTemporaryPassword">复制初始密码</button><ActionFeedback :error="error" :notice="notice"/></AppDialog>
  <AppDialog v-if="showDetail&&detail" title="账户详情" @close="showDetail=false;detail=undefined"><dl class="detail-list"><dt>登录账号</dt><dd>{{detail.loginName}}</dd><dt>姓名</dt><dd>{{detail.displayName}}</dd><dt>学工号</dt><dd>{{detail.personNo}}</dd><template v-if="graduates||detail.roleCodes.includes('USER')"><dt>性别</dt><dd>{{genderName(detail.gender)}}</dd><dt>民族</dt><dd>{{detail.ethnicity||'尚未由本人完善'}}</dd><dt>年龄</dt><dd>{{detail.age??'—'}}</dd><dt>所属班级</dt><dd>{{detail.organizationPath.map(item=>item.name).join(' / ')||orgPath(detail.classId,units)}}</dd><dt>身份证号</dt><dd>{{detail.idCardNumber||'尚未由本人完善'}}</dd><dt>手机号</dt><dd>{{detail.mobileNumber||'尚未由本人完善'}}</dd><dt>现家庭住址</dt><dd>{{detail.currentAddress?`${detail.currentAddress.provinceName}${detail.currentAddress.cityName}${detail.currentAddress.districtName}${detail.currentAddress.detail}`:'尚未由本人完善'}}</dd><dt>户籍地址</dt><dd>{{detail.householdAddress?`${detail.householdAddress.provinceName}${detail.householdAddress.cityName}${detail.householdAddress.districtName}${detail.householdAddress.detail}`:'尚未由本人完善'}}</dd></template><template v-if="graduates"><dt>毕业时间</dt><dd>{{localTime(detail.graduatedAt)}}</dd><dt>毕业原因</dt><dd>{{detail.graduatedReason||'历史毕业档案'}}</dd></template><dt>账户状态</dt><dd>{{zh(detail.lifecycleStatus)}}</dd><dt>安全状态</dt><dd>{{zh(detail.securityStatus)}}</dd><dt>最近登录</dt><dd>{{localTime(detail.lastLoginAt)}}</dd></dl><div v-if="!graduates" class="form-actions"><button class="secondary" :disabled="busy" @click="beginEdit"><Pencil :size="18" aria-hidden="true"/>更正资料</button><button v-if="detail.roleCodes.includes('USER')&&detail.lifecycleStatus==='ACTIVE'" class="primary" :disabled="busy" @click="beginEnrollment"><School :size="18" aria-hidden="true"/>学籍变动</button></div></AppDialog>
  <AppDialog v-if="showEdit&&detail" title="更正账户资料" :busy="busy" @close="showEdit=false;showDetail=true"><form @submit.prevent="saveEdit"><label>姓名<input v-model="edit.displayName" required maxlength="100"></label><label>学工号（不可修改）<input :value="detail.personNo" disabled></label><label>登录账号<input v-model="edit.loginName" required maxlength="100" autocomplete="off"></label><label v-if="detail.roleCodes.includes('USER')">性别（选填）<select v-model="edit.gender"><option value="">未填写</option><option value="MALE">男</option><option value="FEMALE">女</option><option value="OTHER">其他</option></select></label><label v-if="detail.roleCodes.includes('USER')">民族（选填）<input v-model.trim="edit.ethnicity" maxlength="20" placeholder="如：汉族"></label><template v-if="detail.roleCodes.includes('USER')&&detail.profileCompleted"><label>身份证号<input v-model.trim="edit.idCardNumber" required minlength="18" maxlength="18" pattern="[0-9]{17}[0-9Xx]"></label><label>手机号<input v-model.trim="edit.mobileNumber" required maxlength="11" pattern="1[3-9][0-9]{9}"></label><fieldset class="address-edit"><legend>现家庭住址</legend><label>省/自治区/直辖市<select v-model="edit.currentAddress.provinceCode" required @change="changeEditProvince('current')"><option value="">请选择</option><option v-for="item in editDivisions.provinces" :key="item.code" :value="item.code">{{item.name}}</option></select></label><label>市<select v-model="edit.currentAddress.cityCode" required @change="changeEditCity('current')"><option value="">请选择</option><option v-for="item in editDivisions.currentCities" :key="item.code" :value="item.code">{{item.name}}</option></select></label><label>区/县<select v-model="edit.currentAddress.districtCode" required><option value="">请选择</option><option v-for="item in editDivisions.currentDistricts" :key="item.code" :value="item.code">{{item.name}}</option></select></label><label>详细地址<input v-model.trim="edit.currentAddress.detail" required minlength="2" maxlength="200"></label></fieldset><fieldset class="address-edit"><legend>户籍地址</legend><label>省/自治区/直辖市<select v-model="edit.householdAddress.provinceCode" required @change="changeEditProvince('household')"><option value="">请选择</option><option v-for="item in editDivisions.provinces" :key="item.code" :value="item.code">{{item.name}}</option></select></label><label>市<select v-model="edit.householdAddress.cityCode" required @change="changeEditCity('household')"><option value="">请选择</option><option v-for="item in editDivisions.householdCities" :key="item.code" :value="item.code">{{item.name}}</option></select></label><label>区/县<select v-model="edit.householdAddress.districtCode" required><option value="">请选择</option><option v-for="item in editDivisions.householdDistricts" :key="item.code" :value="item.code">{{item.name}}</option></select></label><label>详细地址<input v-model.trim="edit.householdAddress.detail" required minlength="2" maxlength="200"></label></fieldset></template><p v-else-if="detail.roleCodes.includes('USER')" class="notice">身份证号、手机号和地址尚未由本人完成首次填写，管理员暂不能代填，以免绕过首次资料完善流程。</p><label>更正原因<input v-model="reason" required minlength="2" maxlength="500"></label><ActionFeedback :error="error"/><button class="primary" :disabled="busy">保存更正</button></form></AppDialog>
  <AppDialog v-if="showEnrollment&&detail" title="办理学籍变动" :busy="busy" @close="showEnrollment=false;showDetail=true"><form @submit.prevent="saveEnrollment"><label>学生<input :value="`${detail.displayName}（${detail.personNo}）`" disabled></label><label>转入班级<select v-model="enrollment.classId" required><option value="">请选择班级</option><option v-for="unit in classes" :key="unit.id" :value="unit.id">{{orgPath(unit.id,units)}}</option></select></label><label>变动原因<input v-model="reason" required minlength="2" maxlength="500"></label><ActionFeedback :error="error"/><button class="primary" :disabled="busy||!enrollment.classId||enrollment.classId===detail.classId"><School :size="18" aria-hidden="true"/>确认学籍变动</button></form></AppDialog>
  <AppDialog v-if="pendingCommand" :title="`确认${commandNames[pendingCommand]}`" :busy="busy" @close="pendingCommand=undefined"><form @submit.prevent="runCommand"><p>将对已选的 {{selectedCount}} 个账户执行“{{commandNames[pendingCommand]}}”。</p><p v-if="pendingCommand==='graduate'">这些账户将不能登录，现有身份将取消。</p><p v-if="pendingCommand==='delete'">删除须经另一位管理员确认，执行后不能恢复。</p><label>操作原因<input v-model="reason" required minlength="2" maxlength="500"></label><ActionFeedback :error="error"/><button class="primary" :class="{'danger-action':pendingCommand==='delete'}" :disabled="busy">确认{{commandNames[pendingCommand]}}</button></form></AppDialog>
</section></template>
